static inline void dbl_handwritten(const FE& in_x, const FE& in_y, const FE& in_z,
                                   FE& out_x, FE& out_y, FE& out_z) noexcept {
    FE x = in_x, y = in_y, z = in_z;
    FE s = y.square();
    FE l = x.square();
    l.mul_int_assign(3);
    l.half_assign();
    z.mul_assign(y);
    y = s.negate(1);
    y.mul_assign(x);
    x = l.square();
    x.add_assign(y);
    x.add_assign(y);
    s.square_inplace();
    y.add_assign(x);
    y.mul_assign(l);
    y.add_assign(s);
    y.negate_assign(2);
    out_x = x; out_y = y; out_z = z;
}

static inline void madd_handwritten(const FE& X1, const FE& Y1, const FE& Z1,
                                    const FE& X2, const FE& Y2,
                                    FE& out_x, FE& out_y, FE& out_z) noexcept {
    FE px = X1, py = Y1, pz = Z1;
    FE const zz = pz.square();
    FE const u2 = X2 * zz;
    FE s2 = Y2 * zz;
    s2.mul_assign(pz);
    FE const negX1 = px.negate(8);
    FE const h = u2 + negX1;
    pz.mul_assign(h);
    FE const negS2 = s2.negate(1);
    FE const i_val = py + negS2;
    FE h2 = h.square();
    FE const i2 = i_val.square();
    h2.negate_assign(1);
    FE h3 = h2 * h;
    FE t = px * h2;
    px = i2 + h3;
    px.add_assign(t);
    px.add_assign(t);
    t.add_assign(px);
    h3.mul_assign(py);
    py = t * i_val;
    py.add_assign(h3);
    out_x = px; out_y = py; out_z = pz;
}

